from pathlib import Path
import json
root=Path('app')
def read(p): return (root/p).read_text(encoding='utf-8')
def write(p,s): (root/p).write_text(s,encoding='utf-8')

pkg=json.loads(read('package.json'));pkg['version']='10.9.7';write('package.json',json.dumps(pkg,indent=2,ensure_ascii=False))
html=read('public/index.html').replace('id="versionInfo" class="version-info">v10.9.6','id="versionInfo" class="version-info">v10.9.7',1);write('public/index.html',html)
js=read('public/app.js').replace('const atual="10.9.6"','const atual="10.9.7"',1)
js += r'''
// 10.9.7 - Venda Rapida refeita: tela unica compacta, F1 vendedor, F2 cliente, F10 cobrar
let vr1097Seller='';let vr1097Client='';
function vr1097FindPanel(){return [...document.querySelectorAll('section,dialog,.modal,.card,.panel,[role="dialog"]')].find(n=>/venda r[aá]pida/i.test(n.textContent||''))||null}
function vr1097Options(selectId){const s=document.querySelector(selectId);return s?[...s.options].map(o=>({value:o.value,text:o.textContent})):[]}
function vr1097Picker(tipo){
 const isSeller=tipo==='seller',opts=vr1097Options(isSeller?'#vendedorVenda':'#clienteVenda');
 if(isSeller&&!opts.some(o=>o.value))return toast('Nenhum vendedor disponível.');
 document.querySelector('#vr1097Picker')?.remove();const ov=document.createElement('div');ov.id='vr1097Picker';ov.className='vr1097-picker';
 ov.innerHTML=`<div class="vr1097-pickcard"><div class="vr1097-pickhead"><b>${isSeller?'VENDEDOR — F1':'CLIENTE — F2'}</b><button type="button" data-vrclose>×</button></div><input data-vrfilter autocomplete="off" placeholder="Pesquisar..."><div class="vr1097-picklist"></div></div>`;
 document.body.appendChild(ov);const list=ov.querySelector('.vr1097-picklist'),filter=ov.querySelector('[data-vrfilter]');
 function render(q=''){const a=opts.filter(o=>(o.text||'').toLowerCase().includes(q.toLowerCase()));list.innerHTML=a.map(o=>`<button type="button" data-vrvalue="${esc(o.value)}">${esc(o.text)}</button>`).join('')||'<span>Nenhum resultado.</span>'}
 render();filter.focus();filter.addEventListener('input',()=>render(filter.value));ov.addEventListener('click',e=>{if(e.target.closest('[data-vrclose]')||e.target===ov){ov.remove();return}const b=e.target.closest('[data-vrvalue]');if(!b)return;const val=b.dataset.vrvalue;if(isSeller){vr1097Seller=val;const s=document.querySelector('#vendedorVenda');if(s){s.value=val;s.dispatchEvent(new Event('change',{bubbles:true}))}}else{vr1097Client=val;const c=document.querySelector('#clienteVenda');if(c){c.value=val;c.dispatchEvent(new Event('change',{bubbles:true}))}}ov.remove();vr1097Sync()})
}
function vr1097Sync(){const p=vr1097FindPanel();if(!p)return;const sv=p.querySelector('[data-vrseller]'),cl=p.querySelector('[data-vrclient]');const s=document.querySelector('#vendedorVenda'),c=document.querySelector('#clienteVenda');if(s?.value)vr1097Seller=s.value;if(c)vr1097Client=c.value;if(sv)sv.textContent=s?.selectedOptions?.[0]?.textContent||'Selecionar vendedor';if(cl)cl.textContent=c?.selectedOptions?.[0]?.textContent||'Consumidor final'}
function vr1097Charge(){const p=vr1097FindPanel();if(!p||p.offsetParent===null)return false;const s=document.querySelector('#vendedorVenda');if(!s?.value){toast('Selecione o vendedor com F1 antes de cobrar.');vr1097Picker('seller');return true}if(!cart.length&&!cartServicos.length){toast('Adicione pelo menos um item antes de cobrar.');return true}abrirPagamento1096();return true}
function rebuildVendaRapida1097(){
 const p=vr1097FindPanel();if(!p||p.dataset.vr1097==='1')return;p.dataset.vr1097='1';p.classList.add('vr1097-root');
 // descarta integralmente a UI antiga do painel
 p.innerHTML=`<div class="vr1097-shell"><header><b>VENDA RÁPIDA</b><span>F1 vendedor · F2 cliente · F10 cobrar</span></header><div class="vr1097-tools"><button type="button" data-vrseller>F1 · Vendedor</button><button type="button" data-vrclient>F2 · Cliente</button><div class="vr1097-search"><input data-vrsearch autocomplete="off" placeholder="Código, nome ou código de barras"><span>ENTER</span></div></div><div class="vr1097-main"><section class="vr1097-cart"><div class="vr1097-bar">ITENS DA VENDA</div><div data-vrcart></div><footer><div><small>ITENS</small><b data-vritems>0</b></div><div><small>TOTAL</small><strong data-vrtotal>R$ 0,00</strong></div><button type="button" data-vrcharge>COBRAR <kbd>F10</kbd></button></footer></section><section class="vr1097-catalog"><div class="vr1097-bar">CATEGORIAS</div><div data-vrcats class="vr1097-cats"></div><div class="vr1097-bar">PRODUTOS</div><div data-vrproducts class="vr1097-products"></div></section></div></div>`;
 p.querySelector('[data-vrseller]').onclick=()=>vr1097Picker('seller');p.querySelector('[data-vrclient]').onclick=()=>vr1097Picker('client');p.querySelector('[data-vrcharge]').onclick=()=>vr1097Charge();
 const inp=p.querySelector('[data-vrsearch]');inp.addEventListener('input',vr1097Render);inp.addEventListener('keydown',e=>{if(e.key==='Enter'){const q=normalizarBusca(inp.value);const x=produtos.find(z=>z.ativo&&[z.codigo,z.codigoBarras].map(normalizarBusca).includes(q));if(x){add(x.id);inp.value='';vr1097Render()}}});vr1097Sync();vr1097Render()
}
function vr1097Render(){const p=vr1097FindPanel();if(!p?.classList.contains('vr1097-root'))return;const q=normalizarBusca(p.querySelector('[data-vrsearch]')?.value||''),cats=[...new Set(produtos.filter(x=>x.ativo).map(x=>(x.categoria||'Geral').trim()||'Geral'))];let active=p.dataset.vrcat||'Todos';p.querySelector('[data-vrcats]').innerHTML=['Todos',...cats].map(c=>`<button type="button" class="${c===active?'active':''}" data-vrcat="${esc(c)}">${esc(c)}</button>`).join('');const a=produtos.filter(x=>x.ativo&&(active==='Todos'||(x.categoria||'Geral')===active)&&(!q||[x.nome,x.marca,x.codigo,x.codigoBarras,x.categoria].map(normalizarBusca).some(v=>v.includes(q))));p.querySelector('[data-vrproducts]').innerHTML=a.map(x=>`<button type="button" data-vrprod="${x.id}"><b>${esc(x.nome)}</b><small>${money(x.precoVenda)} · Est. ${x.estoque}</small></button>`).join('')||'<span class="muted">Nenhum produto.</span>';p.querySelectorAll('[data-vrcat]').forEach(b=>b.onclick=()=>{p.dataset.vrcat=b.dataset.vrcat;vr1097Render()});p.querySelectorAll('[data-vrprod]').forEach(b=>b.onclick=()=>{add(Number(b.dataset.vrprod));vr1097Render()});const host=p.querySelector('[data-vrcart]');host.innerHTML=cart.map(i=>{const x=produtos.find(z=>z.id===i.id);return x?`<div class="vr1097-item"><span>${esc(x.nome)}</span><b>${i.qtd}×</b><strong>${money(x.precoVenda*i.qtd)}</strong></div>`:''}).join('')+cartServicos.map(i=>{const x=servicos.find(z=>z.id===i.id);return x?`<div class="vr1097-item"><span>${esc(x.nome)}</span><b>${i.qtd}×</b><strong>${money(x.preco*i.qtd)}</strong></div>`:''}).join('');p.querySelector('[data-vritems]').textContent=cart.reduce((s,i)=>s+i.qtd,0)+cartServicos.reduce((s,i)=>s+i.qtd,0);p.querySelector('[data-vrtotal]').textContent=document.querySelector('#total')?.textContent||'R$ 0,00';vr1097Sync()}
document.addEventListener('keydown',e=>{if(e.repeat)return;const p=vr1097FindPanel();if(!p||p.offsetParent===null)return;if(e.key==='F1'){e.preventDefault();vr1097Picker('seller')}else if(e.key==='F2'){e.preventDefault();vr1097Picker('client')}else if(e.key==='F10'){e.preventDefault();vr1097Charge()}},true);
document.addEventListener('click',()=>setTimeout(()=>{rebuildVendaRapida1097();vr1097Render()},20));const vrObs1097=new MutationObserver(()=>rebuildVendaRapida1097());vrObs1097.observe(document.documentElement,{childList:true,subtree:true});setTimeout(rebuildVendaRapida1097,700);
'''
write('public/app.js',js)
css=read('public/style.css')+r'''
/* 10.9.7 Venda Rapida compacta - pagina fixa; scroll apenas nos produtos */
.vr1097-root{overflow:hidden!important;padding:0!important}.vr1097-shell{height:min(620px,calc(100vh - 110px));min-height:430px;display:flex;flex-direction:column;background:var(--card-bg);font-size:12px}.vr1097-shell header{height:34px;flex:0 0 34px;display:flex;align-items:center;justify-content:space-between;padding:0 10px;background:var(--topbar-bg);border-bottom:1px solid var(--border)}.vr1097-shell header b{font-size:13px}.vr1097-shell header span{font-size:10px;color:var(--text-muted)}.vr1097-tools{height:42px;flex:0 0 42px;display:grid;grid-template-columns:150px 150px 1fr;gap:5px;padding:5px;border-bottom:1px solid var(--border)}.vr1097-tools button,.vr1097-tools input{height:31px!important;min-height:31px!important;margin:0!important;font-size:11px!important}.vr1097-search{position:relative}.vr1097-search input{width:100%;padding-right:46px}.vr1097-search span{position:absolute;right:7px;top:9px;font-size:8px;color:var(--text-muted)}.vr1097-main{flex:1;min-height:0;display:grid;grid-template-columns:minmax(280px,39%) minmax(390px,61%);overflow:hidden}.vr1097-cart,.vr1097-catalog{min-height:0;overflow:hidden;border-right:1px solid var(--border);display:flex;flex-direction:column}.vr1097-bar{height:26px;flex:0 0 26px;padding:6px 8px;background:color-mix(in srgb,var(--primary) 18%,var(--card-bg));font-size:10px;font-weight:900}.vr1097-cart>[data-vrcart]{flex:1;min-height:0;overflow:hidden;padding:4px}.vr1097-item{display:grid;grid-template-columns:1fr 34px 78px;gap:5px;align-items:center;min-height:29px;padding:3px 5px;border-bottom:1px solid var(--border);font-size:10px}.vr1097-item strong{text-align:right}.vr1097-cart footer{height:66px;flex:0 0 66px;display:grid;grid-template-columns:55px 1fr 130px;align-items:center;gap:6px;padding:6px;border-top:1px solid var(--border)}.vr1097-cart footer small{display:block;font-size:8px;color:var(--text-muted)}.vr1097-cart footer strong{font-size:18px}.vr1097-cart footer button{height:48px;border:0;border-radius:5px;background:#15951e;color:#fff;font-weight:950;font-size:13px}.vr1097-cart footer kbd{display:block;font-size:9px;background:transparent}.vr1097-cats{height:72px;flex:0 0 72px;display:flex;gap:4px;overflow-x:auto;overflow-y:hidden;padding:4px}.vr1097-cats button{min-width:86px;height:62px;padding:4px;border:1px solid var(--border);border-radius:3px;background:var(--input-bg);font-size:9px}.vr1097-cats button.active{outline:2px solid var(--primary)}.vr1097-products{flex:1;min-height:0;overflow-y:auto!important;overflow-x:hidden;display:grid;grid-template-columns:repeat(4,minmax(90px,1fr));grid-auto-rows:66px;align-content:start;gap:4px;padding:4px}.vr1097-products button{height:66px;padding:5px;border:1px solid var(--border);border-radius:3px;background:var(--input-bg);color:var(--text);text-align:left;overflow:hidden}.vr1097-products b{display:block;font-size:10px;line-height:1.15;max-height:24px;overflow:hidden}.vr1097-products small{display:block;margin-top:5px;font-size:8px;color:var(--text-muted)}.vr1097-picker{position:fixed;inset:0;z-index:15000;background:rgba(0,0,0,.62);display:grid;place-items:center;padding:10px}.vr1097-pickcard{width:min(430px,92vw);max-height:min(520px,88vh);display:flex;flex-direction:column;background:var(--card-bg);border:1px solid var(--border);border-radius:9px;padding:8px}.vr1097-pickhead{display:flex;justify-content:space-between;align-items:center;height:30px}.vr1097-pickhead button{border:0;background:transparent;color:var(--text);font-size:20px}.vr1097-pickcard input{height:34px!important;min-height:34px!important;margin:4px 0!important}.vr1097-picklist{overflow-y:auto;display:grid;gap:3px}.vr1097-picklist button{min-height:34px;text-align:left;font-size:11px}@media(max-width:900px){.vr1097-main{grid-template-columns:38% 62%}.vr1097-products{grid-template-columns:repeat(3,minmax(80px,1fr))}.vr1097-tools{grid-template-columns:120px 120px 1fr}}@media(max-height:650px){.vr1097-shell{height:calc(100vh - 75px);min-height:390px}.vr1097-cats{height:58px;flex-basis:58px}.vr1097-cats button{height:48px}.vr1097-cart footer{height:58px;flex-basis:58px}.vr1097-cart footer button{height:42px}}
'''
write('public/style.css',css)
print('10.9.7: Venda Rapida refeita em tela unica compacta com F1/F2/F10.')